import {existsSync,readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join} from 'node:path';
// Idempotent privacy patch for the Android project generated by Capacitor 7.
const root=process.cwd();
const file=join(root,'android','app','src','main','AndroidManifest.xml');
if(!existsSync(file))throw Error('AndroidManifest.xml ausente; ejecuta npx cap add android.');
const original=readFileSync(file,'utf8');
const match=original.match(/<application\b[\s\S]*?>/);
if(!match)throw Error('No se encontró <application> en AndroidManifest.xml.');
function setAttr(tag,name,value){
 const p=new RegExp('android:'+name+'="[^"]*"');
 return p.test(tag)?tag.replace(p,'android:'+name+'="'+value+'"'):tag.replace(/>$/,' android:'+name+'="'+value+'">');
}
let tag=match[0];
for(const [key,value] of Object.entries({
 allowBackup:'false',fullBackupContent:'@xml/danper_backup_rules',
 dataExtractionRules:'@xml/danper_data_extraction_rules',usesCleartextTraffic:'false'
}))tag=setAttr(tag,key,value);
const xml=join(root,'android','app','src','main','res','xml');
const drawable=join(root,'android','app','src','main','res','drawable');
mkdirSync(xml,{recursive:true});mkdirSync(drawable,{recursive:true});
writeFileSync(file,original.replace(match[0],tag));
writeFileSync(join(xml,'danper_backup_rules.xml'),[
 '<?xml version="1.0" encoding="utf-8"?>',
 '<full-backup-content>',
 '  <exclude domain="root" path="." />',
 '</full-backup-content>',''
].join('\n'));
writeFileSync(join(xml,'danper_data_extraction_rules.xml'),[
 '<?xml version="1.0" encoding="utf-8"?>',
 '<data-extraction-rules>',
 '  <cloud-backup><exclude domain="root" path="." /></cloud-backup>',
 '  <device-transfer><exclude domain="root" path="." /></device-transfer>',
 '</data-extraction-rules>',''
].join('\n'));
writeFileSync(join(drawable,'ic_stat_icon.xml'),[
 '<?xml version="1.0" encoding="utf-8"?>',
 '<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="24dp" android:height="24dp" android:viewportWidth="24" android:viewportHeight="24">',
 '  <path android:fillColor="#FFFFFFFF" android:pathData="M10,2h4v8h8v4h-8v8h-4v-8H2v-4h8z"/>',
 '</vector>',''
].join('\n'));
if(!readFileSync(file,'utf8').includes('android:allowBackup="false"'))throw Error('Bloqueo de backup no confirmado.');
console.log('Manifiesto Android reforzado: backups excluidos, transporte claro deshabilitado.');
